/* Technical Library is a TREE. The root (technical-library/index.html) lists the branches; each branch is a section from tools/library_sections.json.
   Technical Articles is one branch: technical-library/technical-articles/index.html lists the 200 catalogued articles.
   Articles are hand-written, one file each, inside that branch: technical-library/technical-articles/<slug>.html.
   A card links to its article only when that file exists at build time; otherwise it is a "Coming soon" card with no link.
   (older notes follow)
   Source: tools/library_catalogue.json (exported from ELECMETRIC_Technical_Library_Master_Catalogue_200_Articles.xlsx).
   The catalogue is a content roadmap: no article is written or technically reviewed, so every article page says so and is noindex,
   and only the hub and division pages are listed in the sitemap. To publish an article, add its body to tools/library_articles.json
   (keyed by id: {published, updated, body, references, author, reviewer}) and it is rendered as a real article instead of a stub. */
const fs = require('fs'), path = require('path');
const CAT = JSON.parse(fs.readFileSync(path.join(__dirname, 'library_catalogue.json'), 'utf8'));
const SECTIONS = JSON.parse(fs.readFileSync(path.join(__dirname, 'library_sections.json'), 'utf8')).sort((a, b) => a.order - b.order);
const slugify = (s) => String(s).toLowerCase().replace(/&/g, ' and ').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
const articleSlug = (a) => a.url.replace(/^\/technical-library\//, '').replace(/\/$/, '');


